import { useEffect, useState } from "react";
import { useLanguage } from "../../../context/LanguageContext";
import Icon from "../../UI/Icon/Icon";
import styles from "./RoleForm.module.css";

function RoleForm({
    open,
    role,
    permissions = [],
    saving = false,
    error = "",
    onClose,
    onSubmit,
}) {
    const { translations, direction } = useLanguage();
    const t = translations.rolesPermissions || {};

    const [form, setForm] = useState({
        name: "",
        description: "",
        permissionIds: [],
    });

    useEffect(() => {
        if (!open) {
            return;
        }

        setForm({
            name: role?.name || "",
            description: role?.description || "",
            permissionIds: role?.permissionIds || [],
        });
    }, [open, role]);

    if (!open) {
        return null;
    }

    const change = (field, value) => {
        setForm((previous) => ({
            ...previous,
            [field]: value,
        }));
    };

    const togglePermission = (id) => {
        setForm((previous) => ({
            ...previous,
            permissionIds: previous.permissionIds.includes(id)
                ? previous.permissionIds.filter((item) => item !== id)
                : [...previous.permissionIds, id],
        }));
    };

    const toggleGroup = (groupPermissions) => {
        const ids = groupPermissions.map((permission) => permission.id);
        const allSelected = ids.every((id) =>
            form.permissionIds.includes(id)
        );

        setForm((previous) => ({
            ...previous,
            permissionIds: allSelected
                ? previous.permissionIds.filter(
                      (id) => !ids.includes(id)
                  )
                : [...new Set([...previous.permissionIds, ...ids])],
        }));
    };

    const groupedPermissions = permissions.reduce((groups, permission) => {
        const [group] = permission.code.split(".");

        if (!groups[group]) {
            groups[group] = [];
        }

        groups[group].push(permission);
        return groups;
    }, {});

    const submit = (event) => {
        event.preventDefault();
        onSubmit?.(form);
    };

    return (
        <div className={styles.overlay} dir={direction} role="presentation">
            <div
                className={styles.modal}
                role="dialog"
                aria-modal="true"
                aria-labelledby="role-form-title"
            >
                <div className={styles.header}>
                    <div className={styles.heading}>
                        <div className={styles.iconBox}>
                            <Icon name="roles" size={20} />
                        </div>
                        <div>
                            <h2 id="role-form-title">
                                {role ? t.editRole : t.addRole}
                            </h2>
                            <p>{t.formDescription}</p>
                        </div>
                    </div>
                    <button
                        type="button"
                        className={styles.closeButton}
                        onClick={onClose}
                        disabled={saving}
                        aria-label={t.close}
                    >
                        <Icon name="close" size={18} />
                    </button>
                </div>

                <form onSubmit={submit}>
                    <div className={styles.body}>
                        {error && (
                            <div className={styles.error}>{error}</div>
                        )}

                        <div className={styles.fields}>
                            <label>
                                <span>{t.roleName}</span>
                                <input
                                    value={form.name}
                                    onChange={(event) =>
                                        change("name", event.target.value)
                                    }
                                    required
                                    maxLength={100}
                                />
                            </label>

                            <label>
                                <span>{t.roleDescription}</span>
                                <textarea
                                    value={form.description}
                                    onChange={(event) =>
                                        change(
                                            "description",
                                            event.target.value
                                        )
                                    }
                                    maxLength={500}
                                    rows={3}
                                />
                            </label>
                        </div>

                        <div className={styles.permissionsSection}>
                            <div className={styles.permissionsHeader}>
                                <div>
                                    <h3>{t.permissions}</h3>
                                    <p>{t.permissionsDescription}</p>
                                </div>
                                <span>
                                    {form.permissionIds.length} /{" "}
                                    {permissions.length}
                                </span>
                            </div>

                            <div className={styles.permissionGroups}>
                                {Object.entries(groupedPermissions).map(
                                    ([group, groupPermissions]) => {
                                        const selected = groupPermissions.filter(
                                            (permission) =>
                                                form.permissionIds.includes(
                                                    permission.id
                                                )
                                        ).length;

                                        return (
                                            <section
                                                key={group}
                                                className={styles.permissionGroup}
                                            >
                                                <button
                                                    type="button"
                                                    className={styles.groupHeader}
                                                    onClick={() =>
                                                        toggleGroup(
                                                            groupPermissions
                                                        )
                                                    }
                                                >
                                                    <span>
                                                        {t.permissionGroups?.[
                                                            group
                                                        ] || group}
                                                    </span>
                                                    <small>
                                                        {selected}/
                                                        {groupPermissions.length}
                                                    </small>
                                                </button>

                                                <div
                                                    className={
                                                        styles.permissionGrid
                                                    }
                                                >
                                                    {groupPermissions.map(
                                                        (permission) => (
                                                            <label
                                                                key={
                                                                    permission.id
                                                                }
                                                                className={
                                                                    styles.permissionItem
                                                                }
                                                            >
                                                                <input
                                                                    type="checkbox"
                                                                    checked={form.permissionIds.includes(
                                                                        permission.id
                                                                    )}
                                                                    onChange={() =>
                                                                        togglePermission(
                                                                            permission.id
                                                                        )
                                                                    }
                                                                />
                                                                <span>
                                                                    <strong>
                                                                        {t.permissionNames?.[
                                                                            permission.code
                                                                        ] ||
                                                                            permission.name}
                                                                    </strong>
                                                                    <small>
                                                                        {
                                                                            permission.code
                                                                        }
                                                                    </small>
                                                                </span>
                                                            </label>
                                                        )
                                                    )}
                                                </div>
                                            </section>
                                        );
                                    }
                                )}
                            </div>
                        </div>
                    </div>

                    <div className={styles.footer}>
                        <button
                            type="button"
                            className={styles.cancelButton}
                            onClick={onClose}
                            disabled={saving}
                        >
                            {t.cancel}
                        </button>
                        <button
                            type="submit"
                            className={styles.saveButton}
                            disabled={saving}
                        >
                            <Icon
                                name={saving ? "refresh" : "tick"}
                                size={17}
                            />
                            <span>
                                {saving ? t.saving : t.save}
                            </span>
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
}

export default RoleForm;

import { useEffect, useState } from "react";
import { useLanguage } from "../../../context/LanguageContext";
import Icon from "../../UI/Icon/Icon";
import styles from "./StoreForm.module.css";

const emptyForm = {
  storeCode: "",
  storeNameArabic: "",
  storeNameEnglish: "",
  branchCode: "",
  isActive: true,
};

function StoreForm({
  open,
  store,
  branches = [],
  saving = false,
  error = "",
  onClose,
  onSubmit,
}) {
  const { translations, direction } = useLanguage();
  const t = translations.stores;
  const [form, setForm] = useState(emptyForm);

  useEffect(() => {
    if (!open) return;

    setForm(
      store
        ? {
            storeCode: store.storeCode ?? "",
            storeNameArabic: store.storeNameArabic ?? "",
            storeNameEnglish: store.storeNameEnglish ?? "",
            branchCode: store.branchCode ?? "",
            isActive: store.isActive !== false,
          }
        : emptyForm
    );
  }, [open, store]);

  if (!open) return null;

  const update = (key, value) => setForm((current) => ({ ...current, [key]: value }));

  const handleOverlayMouseDown = (event) => {
    if (event.target === event.currentTarget && !saving) onClose();
  };

  const handleSubmit = (event) => {
    event.preventDefault();
    onSubmit(form);
  };

  return (
    <div className={styles.overlay} role="presentation" onMouseDown={handleOverlayMouseDown}>
      <section className={styles.modal} dir={direction} role="dialog" aria-modal="true">
        <header className={styles.header}>
          <div>
            <h2>{store ? t.editStore : t.newStore}</h2>
            <p>{store ? t.editDescription : t.formDescription}</p>
          </div>
          <button
            type="button"
            className={styles.closeButton}
            onClick={onClose}
            disabled={saving}
            aria-label={t.close}
          >
            <Icon name="close" size={18} />
          </button>
        </header>

        <form onSubmit={handleSubmit}>
          <div className={styles.grid}>
            <label>
              <span>{t.code}</span>
              <input
                value={form.storeCode}
                onChange={(e) => update("storeCode", e.target.value)}
                maxLength={20}
                required
              />
            </label>

            <label>
              <span>{t.arabicName}</span>
              <input
                value={form.storeNameArabic}
                onChange={(e) => update("storeNameArabic", e.target.value)}
                maxLength={100}
                required
              />
            </label>

            <label>
              <span>{t.englishName}</span>
              <input
                value={form.storeNameEnglish}
                onChange={(e) => update("storeNameEnglish", e.target.value)}
                maxLength={100}
              />
            </label>

            <label>
              <span>{t.branch}</span>
              <select
                value={form.branchCode}
                onChange={(e) => update("branchCode", e.target.value)}
                required
              >
                <option value="">{t.selectBranch}</option>
                {branches.map((branch) => (
                  <option key={branch.id ?? branch.branchCode} value={branch.branchCode}>
                    {branch.branchNameArabic || branch.branchNameEnglish || branch.branchCode}
                  </option>
                ))}
              </select>
            </label>

            <label className={styles.checkbox}>
              <input
                type="checkbox"
                checked={form.isActive}
                onChange={(e) => update("isActive", e.target.checked)}
              />
              <span>{t.active}</span>
            </label>
          </div>

          {error ? <p className={styles.error}>{error}</p> : null}

          <footer className={styles.footer}>
            <button type="button" className={styles.secondary} onClick={onClose} disabled={saving}>
              {t.cancel}
            </button>
            <button type="submit" className={styles.primary} disabled={saving}>
              {saving ? t.saving : t.save}
            </button>
          </footer>
        </form>
      </section>
    </div>
  );
}

export default StoreForm;

import { useEffect, useMemo, useState } from "react";
import { useLanguage } from "../../../context/LanguageContext";
import Icon from "../../UI/Icon/Icon";
import styles from "./UserForm.module.css";

function UserForm({
    open,
    user,
    roles = [],
    permissions = [],
    saving = false,
    error = "",
    onClose,
    onSubmit,
}) {
    const { translations, direction } = useLanguage();
    const t = translations.users;
    const [form, setForm] = useState({
        username: "",
        password: "",
        role: "",
        permissions: [],
        isActive: true,
    });

    const getRolePermissions = (role) => {
        if (!role?.permissionIds?.length) {
            return [];
        }

        return permissions
            .filter((permission) =>
                role.permissionIds.includes(permission.id)
            )
            .map((permission) => permission.code);
    };

    useEffect(() => {
        if (!open) {
            return;
        }

        const selectedRole = roles.find(
            (role) =>
                role.name?.toLowerCase() === user?.role?.toLowerCase()
        );

        const rolePermissions = getRolePermissions(selectedRole);

        setForm({
            username: user?.username || "",
            password: "",
            role: user?.role || "",
            permissions:
                user?.permissions?.length > 0
                    ? user.permissions
                    : rolePermissions,
            isActive: user?.isActive ?? true,
        });
    }, [open, user, roles, permissions]);

    const groupedPermissions = useMemo(() => {
        return permissions.reduce((groups, permission) => {
            const [group] = permission.code.split(".");

            if (!groups[group]) {
                groups[group] = [];
            }

            groups[group].push(permission);

            return groups;
        }, {});
    }, [permissions]);

    if (!open) {
        return null;
    }

    const change = (field, value) => {
        setForm((previous) => ({
            ...previous,
            [field]: value,
        }));
    };

    const handleRoleChange = (roleName) => {
        const selectedRole = roles.find(
            (role) =>
                role.name?.toLowerCase() === roleName?.toLowerCase()
        );

        const rolePermissions = getRolePermissions(selectedRole);

        setForm((previous) => ({
            ...previous,
            role: roleName,
            permissions: rolePermissions,
        }));
    };

    const togglePermission = (code) => {
        setForm((previous) => ({
            ...previous,
            permissions: previous.permissions.includes(code)
                ? previous.permissions.filter((item) => item !== code)
                : [...previous.permissions, code],
        }));
    };

    const toggleGroup = (groupPermissions) => {
        const codes = groupPermissions.map((item) => item.code);
        const allSelected = codes.every((code) =>
            form.permissions.includes(code)
        );

        setForm((previous) => ({
            ...previous,
            permissions: allSelected
                ? previous.permissions.filter(
                    (code) => !codes.includes(code)
                )
                : [...new Set([...previous.permissions, ...codes])],
        }));
    };

    const submit = (event) => {
        event.preventDefault();
        onSubmit?.(form);
    };

    return (
        <div
            className={styles.overlay}
            dir={direction}
            role="presentation"
        >
            <div
                className={styles.modal}
                role="dialog"
                aria-modal="true"
                aria-labelledby="user-form-title"
            >
                <div className={styles.header}>
                    <div className={styles.heading}>
                        <div className={styles.iconBox}>
                            <Icon name="users" size={20} />
                        </div>

                        <div>
                            <h2 id="user-form-title">
                                {user ? t.editUser : t.addUser}
                            </h2>
                            <p>{t.formDescription}</p>
                        </div>
                    </div>

                    <button
                        type="button"
                        className={styles.closeButton}
                        onClick={onClose}
                        disabled={saving}
                        aria-label={t.close}
                    >
                        <Icon name="close" size={18} />
                    </button>
                </div>

                <form onSubmit={submit}>
                    <div className={styles.body}>
                        {error && (
                            <div className={styles.error}>
                                {error}
                            </div>
                        )}

                        <div className={styles.fields}>
                            <label>
                                <span>{t.username}</span>
                                <input
                                    value={form.username}
                                    onChange={(event) =>
                                        change(
                                            "username",
                                            event.target.value
                                        )
                                    }
                                    required
                                    maxLength={100}
                                    autoComplete="off"
                                />
                            </label>

                            <label>
                                <span>
                                    {user ? t.newPassword : t.password}
                                </span>
                                <input
                                    type="password"
                                    value={form.password}
                                    onChange={(event) =>
                                        change(
                                            "password",
                                            event.target.value
                                        )
                                    }
                                    minLength={user ? undefined : 8}
                                    maxLength={200}
                                    required={!user}
                                    autoComplete="new-password"
                                    placeholder={
                                        user
                                            ? t.passwordOptional
                                            : ""
                                    }
                                />
                            </label>

                            <label>
                                <span>{t.role}</span>
                                <select
                                    value={form.role}
                                    onChange={(event) =>
                                        handleRoleChange(
                                            event.target.value
                                        )
                                    }
                                    required
                                >
                                    <option value="">
                                        {t.selectRole}
                                    </option>

                                    {roles.map((role) => (
                                        <option
                                            key={role.id}
                                            value={role.name}
                                        >
                                            {role.name}
                                        </option>
                                    ))}
                                </select>
                            </label>

                            <label className={styles.statusField}>
                                <span>{t.status}</span>
                                <button
                                    type="button"
                                    className={`${styles.statusToggle} ${form.isActive
                                        ? styles.on
                                        : ""
                                        }`}
                                    onClick={() =>
                                        change(
                                            "isActive",
                                            !form.isActive
                                        )
                                    }
                                    aria-pressed={form.isActive}
                                >
                                    <span>
                                        {form.isActive
                                            ? t.active
                                            : t.inactive}
                                    </span>
                                </button>
                            </label>
                        </div>

                        <div className={styles.permissionsSection}>
                            <div className={styles.permissionsHeader}>
                                <div>
                                    <h3>{t.permissions}</h3>
                                    <p>{t.permissionsDescription}</p>
                                </div>

                                <span>
                                    {form.permissions.length} /{" "}
                                    {permissions.length}
                                </span>
                            </div>

                            <div className={styles.permissionGroups}>
                                {Object.entries(
                                    groupedPermissions
                                ).map(
                                    ([
                                        group,
                                        groupPermissions,
                                    ]) => {
                                        const selected =
                                            groupPermissions.filter(
                                                (item) =>
                                                    form.permissions.includes(
                                                        item.code
                                                    )
                                            ).length;

                                        return (
                                            <section
                                                key={group}
                                                className={
                                                    styles.permissionGroup
                                                }
                                            >
                                                <button
                                                    type="button"
                                                    className={
                                                        styles.groupHeader
                                                    }
                                                    onClick={() =>
                                                        toggleGroup(
                                                            groupPermissions
                                                        )
                                                    }
                                                >
                                                    <span>
                                                        {
                                                            t
                                                                .permissionGroups?.[
                                                            group
                                                            ]
                                                            || group}
                                                    </span>

                                                    <small>
                                                        {selected}/
                                                        {
                                                            groupPermissions.length
                                                        }
                                                    </small>
                                                </button>

                                                <div
                                                    className={
                                                        styles.permissionGrid
                                                    }
                                                >
                                                    {groupPermissions.map(
                                                        (
                                                            permission
                                                        ) => (
                                                            <label
                                                                key={
                                                                    permission.code
                                                                }
                                                                className={
                                                                    styles.permissionItem
                                                                }
                                                            >
                                                                <input
                                                                    type="checkbox"
                                                                    checked={form.permissions.includes(
                                                                        permission.code
                                                                    )}
                                                                    onChange={() =>
                                                                        togglePermission(
                                                                            permission.code
                                                                        )
                                                                    }
                                                                />

                                                                <span>
                                                                    <strong>
                                                                        {
                                                                            t
                                                                                .permissionNames?.[
                                                                            permission.code
                                                                            ]
                                                                            || permission.name}
                                                                    </strong>

                                                                    <small>
                                                                        {
                                                                            permission.code
                                                                        }
                                                                    </small>
                                                                </span>
                                                            </label>
                                                        )
                                                    )}
                                                </div>
                                            </section>
                                        );
                                    }
                                )}
                            </div>
                        </div>
                    </div>

                    <div className={styles.footer}>
                        <button
                            type="button"
                            className={styles.cancelButton}
                            onClick={onClose}
                            disabled={saving}
                        >
                            {t.cancel}
                        </button>

                        <button
                            type="submit"
                            className={styles.saveButton}
                            disabled={saving}
                        >
                            <Icon
                                name={saving ? "refresh" : "tick"}
                                size={17}
                            />

                            <span>
                                {saving ? t.saving : t.save}
                            </span>
                        </button>
                    </div>
                </form>
            </div>
        </div>
    );
}

export default UserForm;

import { createContext, useCallback, useContext, useState } from "react";
import {
    getCurrentUser,
    isAuthenticated,
    login,
    logout as logoutService,
} from "../services/authService";

const AuthContext = createContext(null);

export function AuthProvider({ children }) {
    const [user, setUser] = useState(() => getCurrentUser());
    const [authenticated, setAuthenticated] = useState(() => isAuthenticated());
    const [loading, setLoading] = useState(false);

    const signIn = useCallback(async (username, password) => {
        setLoading(true);

        try {
            const response = await login(username, password);
            setUser(response.user);
            setAuthenticated(true);
            return response;
        } finally {
            setLoading(false);
        }
    }, []);

    const signOut = useCallback(() => {
        logoutService();
        setUser(null);
        setAuthenticated(false);
    }, []);

    const value = {
        user,
        authenticated,
        loading,
        signIn,
        signOut,
    };

    return (
        <AuthContext.Provider value={value}>
            {children}
        </AuthContext.Provider>
    );
}

export function useAuth() {
    const context = useContext(AuthContext);

    if (!context) {
        throw new Error("useAuth must be used within an AuthProvider.");
    }

    return context;
}

